import { readFile, writeFile, rename, mkdir } from "node:fs/promises";
import { dirname } from "node:path";
import { randomBytes } from "node:crypto";

// Keeps books in memory and mirrors every change to a JSON file.
// Writes go to a temp file first and are renamed into place, so a crash
// mid-write never leaves a half-written books.json behind.
export async function openStore(file) {
  let books = [];
  try {
    const parsed = JSON.parse(await readFile(file, "utf8"));
    if (!Array.isArray(parsed)) throw new Error("expected a JSON array");
    books = parsed;
  } catch (err) {
    if (err.code !== "ENOENT") {
      // Refuse to start rather than overwrite a file we couldn't read.
      throw new Error(`Could not read ${file}: ${err.message}`);
    }
  }

  let queue = Promise.resolve();
  function persist() {
    const snapshot = JSON.stringify(books, null, 2) + "\n";
    const run = async () => {
      await mkdir(dirname(file), { recursive: true });
      const tmp = `${file}.${process.pid}.tmp`;
      await writeFile(tmp, snapshot);
      await rename(tmp, file);
    };
    queue = queue.then(run, run);
    return queue;
  }

  return {
    all() {
      return books.slice();
    },
    get(id) {
      return books.find((b) => b.id === id);
    },
    async add({ title, author, notes }) {
      const book = {
        id: randomBytes(6).toString("base64url"),
        title,
        author,
        notes,
        addedAt: new Date().toISOString(),
        finishedAt: null,
      };
      books.push(book);
      await persist();
      return book;
    },
    async finish(id) {
      const book = books.find((b) => b.id === id);
      if (!book) return undefined;
      if (!book.finishedAt) {
        book.finishedAt = new Date().toISOString();
        await persist();
      }
      return book;
    },
  };
}

