import { createServer } from "node:http";
import { openStore } from "./store.js";

const MAX_BODY = 64 * 1024;
const LIMITS = { title: 300, author: 300, notes: 20000 };

const esc = (s) =>
  String(s ?? "").replace(
    /[&<>"']/g,
    (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c],
  );

const fmtDate = (iso) =>
  new Date(iso).toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" });

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(title)}</title>
<style>
  body { font: 16px/1.5 system-ui, sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; color: #222; }
  h1 a { color: inherit; text-decoration: none; }
  ul { padding: 0; list-style: none; }
  li { display: flex; justify-content: space-between; align-items: center; gap: 1rem; padding: .5rem 0; border-bottom: 1px solid #eee; }
  .muted { color: #777; }
  .error { color: #b00020; }
  form.add label { display: block; margin-top: .75rem; }
  form.add input, form.add textarea { width: 100%; box-sizing: border-box; font: inherit; padding: .4rem; }
  button { font: inherit; cursor: pointer; }
  .notes { white-space: pre-wrap; background: #f7f7f7; padding: 1rem; border-radius: 4px; }
</style>
</head>
<body>
<h1><a href="/">My books</a></h1>
${body}
</body>
</html>`;
}

function bookItem(book) {
  const link = `<a href="/books/${esc(book.id)}">${esc(book.title)}</a> <span class="muted">by ${esc(book.author)}</span>`;
  if (book.finishedAt) {
    return `<li><span>${link}</span><span class="muted">${fmtDate(book.finishedAt)}</span></li>`;
  }
  return `<li><span>${link}</span>
  <form method="post" action="/books/${esc(book.id)}/finish"><button>Mark finished</button></form></li>`;
}

function homePage(books, { errors = [], values = {} } = {}) {
  const reading = books.filter((b) => !b.finishedAt);
  const finished = books
    .filter((b) => b.finishedAt)
    .sort((a, b) => b.finishedAt.localeCompare(a.finishedAt));
  const list = (items, empty) =>
    items.length ? `<ul>${items.map(bookItem).join("")}</ul>` : `<p class="muted">${empty}</p>`;

  return layout(
    "My books",
    `<h2>Currently reading</h2>
${list(reading, "Nothing on the go right now.")}
<h2>Finished</h2>
${list(finished, "No finished books yet.")}
<h2>Add a book</h2>
${errors.map((e) => `<p class="error">${esc(e)}</p>`).join("")}
<form class="add" method="post" action="/books">
  <label>Title <input name="title" required maxlength="${LIMITS.title}" value="${esc(values.title)}"></label>
  <label>Author <input name="author" required maxlength="${LIMITS.author}" value="${esc(values.author)}"></label>
  <label>Notes <textarea name="notes" rows="4" maxlength="${LIMITS.notes}">${esc(values.notes)}</textarea></label>
  <p><button>Add book</button></p>
</form>`,
  );
}

function bookPage(book) {
  const status = book.finishedAt
    ? `Finished ${fmtDate(book.finishedAt)}`
    : `Reading since ${fmtDate(book.addedAt)}`;
  const finishForm = book.finishedAt
    ? ""
    : `<form method="post" action="/books/${esc(book.id)}/finish"><button>Mark finished</button></form>`;
  return layout(
    book.title,
    `<h2>${esc(book.title)}</h2>
<p>by ${esc(book.author)}</p>
<p class="muted">${status}</p>
<h3>Notes</h3>
${book.notes ? `<div class="notes">${esc(book.notes)}</div>` : `<p class="muted">No notes.</p>`}
${finishForm}
<p><button type="button" onclick="navigator.clipboard.writeText(location.href).then(() => this.textContent = 'Link copied')">Copy link to this book</button></p>
<p><a href="/">&larr; All books</a></p>`,
  );
}

function send(res, status, html, headers = {}) {
  res.writeHead(status, { "content-type": "text/html; charset=utf-8", ...headers });
  res.end(html);
}

const redirect = (res, location) => {
  res.writeHead(303, { location });
  res.end();
};

const notFound = (res) =>
  send(res, 404, layout("Not found", `<p>That book doesn't exist.</p><p><a href="/">&larr; All books</a></p>`));

function readForm(req) {
  return new Promise((resolve, reject) => {
    let size = 0;
    const chunks = [];
    req.on("data", (chunk) => {
      size += chunk.length;
      if (size > MAX_BODY) {
        reject(Object.assign(new Error("Request too large"), { status: 413 }));
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });
    req.on("end", () => resolve(new URLSearchParams(Buffer.concat(chunks).toString("utf8"))));
    req.on("error", reject);
  });
}

function validate(form) {
  const values = {
    title: (form.get("title") ?? "").trim(),
    author: (form.get("author") ?? "").trim(),
    notes: (form.get("notes") ?? "").trim(),
  };
  const errors = [];
  if (!values.title) errors.push("Title is required.");
  if (!values.author) errors.push("Author is required.");
  for (const [field, max] of Object.entries(LIMITS)) {
    if (values[field].length > max) errors.push(`${field[0].toUpperCase() + field.slice(1)} is too long.`);
  }
  return { values, errors };
}

export async function createApp({ dataFile }) {
  const store = await openStore(dataFile);

  return createServer(async (req, res) => {
    try {
      const { pathname } = new URL(req.url, "http://localhost");
      const bookMatch = pathname.match(/^\/books\/([\w-]+)$/);
      const finishMatch = pathname.match(/^\/books\/([\w-]+)\/finish$/);

      if (req.method === "GET" && pathname === "/") {
        return send(res, 200, homePage(store.all()));
      }
      if (req.method === "POST" && pathname === "/books") {
        const { values, errors } = validate(await readForm(req));
        if (errors.length) return send(res, 400, homePage(store.all(), { errors, values }));
        const book = await store.add(values);
        return redirect(res, "/#" + book.id);
      }
      if (req.method === "GET" && bookMatch) {
        const book = store.get(bookMatch[1]);
        return book ? send(res, 200, bookPage(book)) : notFound(res);
      }
      if (req.method === "POST" && finishMatch) {
        const book = await store.finish(finishMatch[1]);
        if (!book) return notFound(res);
        // Go back to wherever the button was clicked (home or book page).
        const back = req.headers.referer ? new URL(req.headers.referer).pathname : "/";
        return redirect(res, back === `/books/${book.id}` ? back : "/");
      }
      return notFound(res);
    } catch (err) {
      const status = err.status ?? 500;
      if (status === 500) console.error(err);
      send(res, status, layout("Error", `<p>Something went wrong.</p>`));
    }
  });
}

