import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { mkdtemp, rm, readFile, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createApp } from "../src/app.js";

let dir, dataFile, server, base;

async function start() {
  server = await createApp({ dataFile });
  await new Promise((r) => server.listen(0, "127.0.0.1", r));
  base = `http://127.0.0.1:${server.address().port}`;
}
const stop = () => new Promise((r) => server.close(r));

const post = (path, fields = {}, headers = {}) =>
  fetch(base + path, {
    method: "POST",
    body: new URLSearchParams(fields),
    redirect: "manual",
    headers,
  });

async function addBook(fields) {
  const res = await post("/books", fields);
  expect(res.status).toBe(303);
  return res.headers.get("location").slice(2); // "/#<id>"
}

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), "books-"));
  dataFile = join(dir, "books.json");
  await start();
});
afterEach(async () => {
  await stop();
  await rm(dir, { recursive: true, force: true });
});

describe("reading list", () => {
  it("shows empty lists and the add form", async () => {
    const html = await (await fetch(base + "/")).text();
    expect(html).toContain("Currently reading");
    expect(html).toContain("Finished");
    expect(html).toContain('action="/books"');
  });

  it("adds a book, shows it as reading, and links to its page", async () => {
    const id = await addBook({ title: "Dune", author: "Frank Herbert", notes: "Spice!\nLine two" });
    const home = await (await fetch(base + "/")).text();
    const reading = home.split("<h2>Finished</h2>")[0];
    expect(reading).toContain(`href="/books/${id}"`);

    const page = await fetch(`${base}/books/${id}`);
    expect(page.status).toBe(200);
    const html = await page.text();
    expect(html).toContain("Dune");
    expect(html).toContain("Frank Herbert");
    expect(html).toContain("Spice!\nLine two");
  });

  it("marks a book finished and moves it to the finished list", async () => {
    const id = await addBook({ title: "Emma", author: "Jane Austen" });
    const res = await post(`/books/${id}/finish`);
    expect(res.status).toBe(303);

    const [reading, finished] = (await (await fetch(base + "/")).text()).split("<h2>Finished</h2>");
